import{_ as i,C as r,c as l,o as c,a9 as d,G as t}from"./chunks/framework.DuenUNqn.js";const m=JSON.parse('{"title":"Fabric、Forge 及 Quilt 服务端世界创建","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/wiki"},{"title":"Terra","link":"/wiki/Terra"},{"title":"getting-started","link":"/wiki/Terra/getting-started"},{"title":"Fabric、Forge 及 Quilt 服务端世界创建","link":"/wiki/Terra/getting-started/fabric-forge-and-quilt-server-world-creation"}]},"headers":[],"relativePath":"wiki/Terra/getting-started/fabric-forge-and-quilt-server-world-creation.md","filePath":"wiki/Terra/getting-started/fabric-forge-and-quilt-server-world-creation.md"}'),s={name:"wiki/Terra/getting-started/fabric-forge-and-quilt-server-world-creation.md"};function n(p,e,g,u,b,f){const o=r("NolebaseGitContributors"),a=r("NolebaseGitChangelog");return c(),l("div",null,[e[0]||(e[0]=d('<h1 id="fabric、forge-及-quilt-服务端世界创建" tabindex="-1">Fabric、Forge 及 Quilt 服务端世界创建 <a class="header-anchor" href="#fabric、forge-及-quilt-服务端世界创建" aria-label="Permalink to &quot;Fabric、Forge 及 Quilt 服务端世界创建&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">提示</p><p>本教程适用于 Fabric、Forge 及 Quilt 版本的 Terra。</p><p><a href="./">其他平台的安装方法见此</a> &gt;</p></div><div class="warning custom-block"><p class="custom-block-title">警告</p><p>我们会将服务器的默认世界替换为新的 Terra 世界。</p><p>因为我们正在对世界进行改动，请确保你在进行任何破坏性改动前<strong>备份了必要文件</strong>！</p><p>目前难以改变已有世界使用的生成器。这是一个件好事，因为切换世界生成器后产生的新区块会与原区块产生割裂。</p></div><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><ol><li>确保服务器已经关闭。</li><li>如果你没有读过上述的警告内容，请对服务器文件夹内重要的世界进行备份。</li><li>通过如下步骤修改配置文件，使用新的生成器：</li><li>使用任意文本编辑器，打开服务器目录内的 <code>server.properties</code> 文件。</li><li>将 <code>level-type</code> 设置为 <code>level-type=terra:&lt;配置 ID&gt;/&lt;配置 ID&gt;</code>（默认包为 <code>terra:overworld/overworld</code>）。包 ID 必须全部小写，例如一个名字叫 <code>EXAMPLE</code> 的包，在这里填入的内容为 <code>terra:example/example</code>。</li></ol><p>::: attention</p><p>若配置文件中没有 <code>level-type</code> 键，请自行添加在文件末尾。</p><p>::: 4. 删除已有世界文件夹或将其重命名（如 <code>world_backup</code>）。世界的名称可以在 <code>server.properties</code> 下的 <code>level-name</code> 找到。默认为 <code>world</code>。 5. 启动服务器。</p><div class="info custom-block"><p class="custom-block-title">信息</p><p>你的服务器应该会在启动后重新生成世界。</p></div><ol start="6"><li>加入服务器并检查新的世界是否使用了 Terra 生成器。</li></ol><p>如果你正确按照上述步骤且没有出现错误，那么你就成功在服务端生成了一个 Terra 世界！</p><h2 id="问题排除" tabindex="-1">问题排除 <a class="header-anchor" href="#问题排除" aria-label="Permalink to &quot;问题排除&quot;">​</a></h2><p>如果你在世界设置过程中碰到了问题，请确保你仔细按照各个步骤进行了设置。在服务端日志中检查可能出现的报错，并尝试自行排除问题所在。</p><p>如果你未能成功创建世界，并且尝试自行解决无果，随时可以<a href="./../contact-and-support">寻求帮助</a>并提供相关信息，尤其是上述的日志！</p>',14)),t(o),t(a)])}const k=i(s,[["render",n]]);export{m as __pageData,k as default};
